/* Private upload / Runpod selection. No model is started by upload or page load. */
(()=>{'use strict';
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const endpoint=document.currentScript.dataset.endpoint,base=endpoint?new URL(endpoint):null;
 let reviewer=localStorage.getItem('spikeagent-reviewer-id');if(!reviewer){reviewer=crypto.randomUUID();localStorage.setItem('spikeagent-reviewer-id',reviewer);}
 const key='spikeagent-server-curation-v1:'+reviewer;let token='',paused=false,xhr=null,selectedData=null,workspace=null,options=[],busy=false;
 const saved=()=>{try{return JSON.parse(localStorage.getItem(key)||'{}');}catch{return {};}};
 let qualityContext=null;try{const c=JSON.parse(localStorage.getItem('spikeagent-quality-context:'+reviewer)||'null');if(c&&typeof c.dataset_id==='string'&&/^[a-f0-9]{64}$/.test(c.mat_sha256)&&/^[a-f0-9]{64}$/.test(c.state_sha256)&&Array.isArray(c.units)&&c.units.length>0&&c.units.length<=10000&&c.units.every(u=>Number.isInteger(u.cluster_id)))qualityContext=c;}catch{}
 $('#quality-import-scope').textContent=qualityContext?(qualityContext.channel||qualityContext.dataset_id)+' · grouping '+qualityContext.state_sha256.slice(0,8):'Open a dataset, then return here to import scores for its current grouping.';
 $('#import-quality-scores').disabled=!qualityContext;$('#import-quality-scores').onclick=()=>ReviewQuality.open(qualityContext,()=>{$('#quality-import-status').textContent='Quality scores updated for this grouping.';});
 const remember=value=>localStorage.setItem(key,JSON.stringify({...saved(),...value}));
 async function api(op,body={},auth=true){if(!base)throw Error('Open this page from the deployed website');const response=await fetch(new URL('api/compute/'+op,base),{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body)});let value;try{value=await response.json();}catch{throw Error('Runpod is unavailable. Retry when it is online.');}if(!response.ok)throw Error(value.error||'Request failed');return value;}
 function message(text,error=false){$('#upload-message').textContent=text;$('#upload-message').classList.toggle('error',error);}
 async function guarded(fn){if(busy)return;busy=true;try{await fn();}catch(e){message(e.message,true);}finally{busy=false;}}
 function tab(name){for(const button of document.querySelectorAll('[data-source]')){const active=button.dataset.source===name;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));}$('#runpod-panel').hidden=name!=='runpod';$('#upload-panel').hidden=name!=='upload';location.hash=name;}
 for(const button of document.querySelectorAll('[data-source]'))button.onclick=()=>tab(button.dataset.source);
 function rows(host,values,open){host.innerHTML=values.length?values.map(r=>'<article class="dataset-row"><div><strong>'+esc(r.recording_id||r.dataset_id)+'</strong><p>'+esc(r.n_spikes!=null?r.n_spikes.toLocaleString()+' spikes':'Saved v'+r.version)+'</p></div><button data-id="'+esc(r.dataset_id||r.workspace_id)+'">Open in curation</button></article>').join(''):'<p class="muted">None yet.</p>';for(const [i,button] of [...host.querySelectorAll('button')].entries())button.onclick=()=>guarded(()=>open(values[i]));}
 async function catalog(){const result=await api('datasets');rows($('#runpod-datasets'),result.datasets.filter(r=>r.source_kind!=='private_upload'&&!window.PublicData?.has(r.dataset_id)),r=>openData(r.dataset_id,true));rows($('#uploaded-datasets'),result.datasets.filter(r=>r.source_kind==='private_upload'),r=>openData(r.dataset_id,true));const copies=(await api('workspaces')).workspaces;rows($('#saved-sessions'),copies,async r=>{await openData(r.dataset_id,false,r.workspace_id);enter();});}
 async function openData(dataset,go=false,id=null){const view=await api('open',{dataset_id:dataset,...(id?{workspace_id:id}:{})});selectedData=dataset;workspace=view;remember({workspace_id:view.state.workspace_id,dataset_id:dataset,source:view.selected?.source,target:view.selected?.target,agent:saved().agent||'Agent_1',draft:null});if(go)enter();return view;}
 function enter(){location.href='server-curation.html';}
 function progress(received,total){const percent=total?Math.min(100,received/total*100):0;$('#upload-progress').value=percent;$('#upload-bytes').textContent=percent.toFixed(1)+'% · '+(received/1048576).toFixed(1)+' / '+(total/1048576).toFixed(1)+' MiB';}
 function chunk(uploadId,index,offset,blob,received,total){return new Promise((resolve,reject)=>{xhr=new XMLHttpRequest();xhr.open('POST',new URL('api/compute/upload-chunk?'+new URLSearchParams({upload_id:uploadId,file:index,offset}),base));xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('Authorization','Bearer '+token);xhr.upload.onprogress=e=>progress(received+e.loaded,total);xhr.onerror=()=>reject(Error('Connection interrupted. Click Upload & validate to resume.'));xhr.onabort=()=>reject(Error('Upload paused. Click Upload & validate to resume.'));xhr.onload=()=>{let value;try{value=JSON.parse(xhr.responseText);}catch{return reject(Error('Upload connection failed. Retry to resume.'));}if(xhr.status!==200)return reject(Error(value.error||'Upload failed'));resolve(value);};xhr.send(blob);});}
 async function upload(){const files=[...$('#dataset-files').files],recording=$('#recording-name').value.trim();if(!files.length)throw Error('Choose your dataset files');if(!recording)throw Error('Enter the recording/session name');const total=files.reduce((n,f)=>n+f.size,0);if(total>256*1048576)throw Error('Choose files up to 256 MiB total');
  const signature=JSON.stringify([recording,...files.map(f=>[f.name,f.size,f.lastModified])]),resume=saved().upload;
  let state;
  if(resume?.signature===signature){try{state=await api('upload-status',{upload_id:resume.id});}catch{}}
  if(!state)state=await api('upload-create',{recording_id:recording,files:files.map(f=>({name:f.name,size:f.size}))});remember({upload:{signature,id:state.upload_id}});
  $('#ready-panel').hidden=true;$('#agent-options').hidden=true;selectedData=null;workspace=null;$('#dataset-files').disabled=true;$('#recording-name').disabled=true;paused=false;$('#start-upload').disabled=true;$('#pause-upload').disabled=false;$('#upload-progress-panel').hidden=false;$('#upload-stage').textContent='Uploading to Runpod';message('');
  try{
   if(state.status==='uploading')for(let i=0;i<files.length;i++){let offset=state.files[i].received;while(offset<files[i].size){if(paused)throw Error('Upload paused. Click Upload & validate to resume.');const next=Math.min(offset+state.chunk_bytes,files[i].size);state=await chunk(state.upload_id,i,offset,files[i].slice(offset,next),state.received,total);offset=state.files[i].received;progress(state.received,total);}}
   if(paused)return;state=await api('upload-finish',{upload_id:state.upload_id});$('#pause-upload').disabled=true;$('#upload-stage').textContent='Upload 100% · validating data';progress(total,total);$('#upload-progress').removeAttribute('value');
   while(['queued','validating'].includes(state.status)){message(state.message);await new Promise(r=>setTimeout(r,1000));state=await api('upload-status',{upload_id:state.upload_id});}
   $('#upload-progress').value=100;if(state.status!=='complete')throw Error(state.message||'Validation failed');message(state.message);remember({upload:null});await catalog();await ready(state.result.dataset_id,state.result);
  }finally{$('#start-upload').disabled=false;$('#pause-upload').disabled=true;$('#dataset-files').disabled=false;$('#recording-name').disabled=false;}
 }
 async function ready(dataset,result){await openData(dataset);$('#ready-panel').hidden=false;$('#ready-summary').textContent=(result.recording_id||dataset)+' · '+result.n_spikes.toLocaleString()+' spikes · '+workspace.units.length+' clusters';$('#ready-panel').scrollIntoView({behavior:'smooth',block:'start'});}
 $('#dataset-files').onchange=()=>{const file=$('#dataset-files').files[0];if(file&&!$('#recording-name').value)$('#recording-name').value=file.name.replace(/\.(mat|json|gz)$/i,'').slice(0,120);};
 $('#start-upload').onclick=()=>guarded(upload);$('#pause-upload').onclick=()=>{paused=true;xhr?.abort();};$('#continue-curation').onclick=enter;
 $('#show-agent-options').onclick=()=>guarded(async()=>{$('#agent-options').hidden=!$('#agent-options').hidden;$('#show-agent-options').setAttribute('aria-expanded',String(!$('#agent-options').hidden));if($('#agent-options').hidden)return;options=(await api('agent-options')).agents;$('#upload-agent').innerHTML=options.map(r=>'<option value="'+r.agent_id+'">'+esc(r.label)+'</option>').join('');availability();});
 function availability(){const option=options.find(r=>r.agent_id===$('#upload-agent').value);$('#start-agent').disabled=!option?.available;$('#agent-availability').textContent=option?.available?'Ready · up to '+option.max_calls+' requests per batch':option?.reason||'Agent is offline. You can start curation without it.';}
 $('#upload-agent').onchange=availability;
 $('#start-agent').onclick=()=>guarded(async()=>{if(!workspace)throw Error('Open the validated dataset first');const slot=$('#upload-agent').value;let job=await api('agent-start',{workspace_id:workspace.state.workspace_id,version:workspace.state.version,source:workspace.selected?.source??null,target:workspace.selected?.target??null,agent_id:slot,scope:$('#agent-scope').value,confirm:true,request_id:crypto.randomUUID()});remember({agent:slot,agent_job:job.job_id});$('#start-agent').disabled=true;$('#agent-progress').hidden=false;$('#continue-curation').textContent='Continue to curation';
  while(['queued','running'].includes(job.status)){$('#agent-progress').max=job.total||1;$('#agent-progress').value=job.completed||0;$('#agent-message').textContent=job.message+' · '+job.completed+' / '+job.total;await new Promise(r=>setTimeout(r,2000));job=await api('agent-status',{job_id:job.job_id});}
  $('#agent-message').textContent=job.message+' · '+job.completed+' / '+job.total;$('#agent-progress').value=job.completed;availability();
 });
 (async()=>{try{if(window.PublicData?.configured){const demos=await PublicData.ready();$('#public-datasets').innerHTML=demos.map(r=>'<article class="dataset-row"><div><strong>'+esc(r.label)+'</strong><p>'+r.n_spikes.toLocaleString()+' spikes · '+(r.bytes/1048576).toFixed(1)+' MiB</p><a href="'+r.url+'" download="'+esc(r.dataset_id)+'.working.json.gz">Download complete data</a></div><a class="public-open" href="review-studio.html?public='+encodeURIComponent(r.dataset_id)+'">Open public demo</a></article>').join('');}if(!base)throw Error('Open this page from the deployed website');token=saved().token||'';if(!token){token=(await api('session',{},false)).token;remember({token});}await catalog();$('#connection-status').textContent='Connected to Runpod · private sessions';$('#start-upload').disabled=false;tab(location.hash==='#upload'?'upload':'runpod');}catch(e){$('#connection-status').textContent=(window.PublicData?.rows?.length?'Public demos are ready. Runpod connection: ':'')+e.message;$('#connection-status').classList.add('error');}})();
})();
